entries[179887] = { ["name"] = "Queensguard Greathelm", ["text"] = "Binds when picked up\nHead Plate\n38 Armor\n+16 [Strength or Intellect]\n+23 Stamina\n+ 10 Critical Strike\n+ 22 Haste\nDurability 100 / 100\nComplete Chapter 8 of your Covenant Campaign\n\nQueensguard Warbark (0/9)\nQueensguard Cloak\nQueensguard Greathelm\nQueensguard Chestplate\nQueensguard Sabatons\nQueensguard Gauntlets\nQueensguard Greaves\nQueensguard Pauldrons\nQueensguard Girdle\nQueensguard Vambraces\n(3) Set : Increases your out-of-combat regeneration in outdoor Shadowland zones. While in your Covenant's realm, the regeneration amount is increased.\n(5) Set : Soulshape's duration is increased by 4 sec and Flicker grants a short burst of speed while in outdoor Shadowland zones.\n(8) Set : Your spells and abilities have a low chance to summon a Fae Guardian to protect you for 30 sec, increasing your Primary Stat by 60 while alive and periodically healing 5 nearby allies for 450 health.\nSell Price:" }
entries[179888] = { ["name"] = "Queensguard Chestplate", ["text"] = "Binds when picked up\nChest Plate\n51 Armor\n+16 [Strength or Intellect]\n+23 Stamina\n+ 22 Critical Strike\n+ 9 Haste\nDurability 140 / 140\nComplete Chapter 3 of your Covenant Campaign\n\nQueensguard Warbark (0/9)\nQueensguard Cloak\nQueensguard Greathelm\nQueensguard Chestplate\nQueensguard Sabatons\nQueensguard Gauntlets\nQueensguard Greaves\nQueensguard Pauldrons\nQueensguard Girdle\nQueensguard Vambraces\n(3) Set : Increases your out-of-combat regeneration in outdoor Shadowland zones. While in your Covenant's realm, the regeneration amount is increased.\n(5) Set : Soulshape's duration is increased by 4 sec and Flicker grants a short burst of speed while in outdoor Shadowland zones.\n(8) Set : Your spells and abilities have a low chance to summon a Fae Guardian to protect you for 30 sec, increasing your Primary Stat by 60 while alive and periodically healing 5 nearby allies for 450 health.\nSell Price:" }
