entries[179919] = { ["name"] = "Shadowy Rabbit's Foot", ["text"] = "Optional Crafting Reagent\n\nProvides the following property: Slightly increase move speed\n\"An Optional Reagent that can be crafted into a piece of armor, slightly increasing the wearer's run speed.\"\nSell Price:" }
entries[179921] = { ["name"] = "Hydra Gutter", ["text"] = "Quest Item\nUnique\nUse: Cut open a dead Devouring Hydra. Careful not to stab any of the fae within. (2 Sec Cooldown)" }
entries[179922] = { ["name"] = "Animacone", ["text"] = "Quest Item\n\"A seed of condensed anima, fallen from one of the celestial trees. It's covered in saliva.\"" }
entries[179923] = { ["name"] = "Attack Battlehorn", ["text"] = "Quest Item\nUnique\nUse: Signal the troops to press the attack.\n\"A powerful horn to help signal an attack.\"" }
entries[179924] = { ["name"] = "Light-Infused Jacket", ["text"] = "Binds when picked up\nChest Leather\n11 Armor\n+8 [Agility or Intellect]\n+11 Stamina\nDurability 140 / 140\nUse: Gain a shield for 1 hour that absorbs up to 482 Holy Damage.\n3 Charges\nSell Price:" }
