entries[179927] = { ["name"] = "Glowing Endmire Stinger", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 5 Mastery\nEquip: Targets under 20% health are stung dealing [source value] Shadow damage over 15 sec, returning 100% of the damage to you as healing. This effect can only occur once every 15 seconds. (15s cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[179928] = { ["name"] = "Cell Chain Pull" }
entries[179929] = { ["name"] = "Heart of the Fallen Tree", ["text"] = "Quest Item\nUnique\nUse: Attune the filled heart of the tree shrines around Tirna Glayn." }
entries[179937] = { ["name"] = "Sliver of Burgeoning Ambition", ["text"] = "Binds when picked up\nUnique\nDuration: 1 day (real time)\nUse: Increase your Primary Stat by 27 but reduce your maximum health by 5% for 1 min. Stacks up to 10 times. Only usable outdoors in the Shadowlands.\n5 Charges\n\"Ambition can outstrip prudence.\"\nSell Price:" }
entries[179938] = { ["name"] = "Crumbling Pride Extractors", ["text"] = "Binds when picked up\nUnique\nDuration: 1 day (real time)\nUse: Extracts an enemy's vitality dealing 3205 Shadow damage and granting you 7363 health every 5 sec for 20 sec. Only usable outdoors in the Shadowlands. (1 Min Cooldown)\n5 Charges\nSell Price:" }
entries[179939] = { ["name"] = "Wriggling Spider Sac", ["text"] = "Binds when picked up\nDuration: 1 day (real time)\nUse: Throw the Wriggling Spider Sac and see how many spiders pounce on your target!!! Only usable outdoors in the Shadowlands. (2 Min Cooldown)\n\"Oooh they are ready to hatch!\"\nSell Price:" }
entries[179940] = { ["name"] = "Selfless Forgelite's Vest", ["text"] = "Binds when picked up\nChest Mail\n33 Armor\n+15 [Agility or Intellect]\n+22 Stamina\n+ 9 Critical Strike\n+ 20 Mastery\nDurability 165 / 165\nComplete Chapter 8 of your Covenant Campaign\n\nChain of the Selfless (0/9)\nSelfless Forgelite's Vest\nSelfless Forgelite's Boots\nSelfless Forgelite's Gloves\nSelfless Forgelite's Helm\nSelfless Forgelite's Breeches\nSelfless Forgelite's Spaulders\nSelfless Forgelite's Belt\nSelfless Forgelite's Wristwraps\nSelfless Forgelite's Drape\n(3) Set : Increases your out-of-combat regeneration in outdoor Shadowland zones. While in your Covenant's realm, the regeneration amount is increased.\n(5) Set : Phial of Serenity grants 70 Primary Stat for 30 sec. Removing a disease, poison, curse, or bleed increases the amount granted by 50%.\n(8) Set : Your spells and abilities have a chance to cause your target to erupt in a blinding light dealing 577 Arcane damage or healing an ally for 709 health.\nSell Price:" }
