entries[180413] = { ["name"] = "Shadeleaf Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 23\nSell Price:\n\"The shadeleaf runestag are bred for their ferocity as well as their beauty by the Wild Hunt. They feel no fear charging into the den of any predator.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180414] = { ["name"] = "Wakener's Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Runestags enjoy lying near wildseeds. The Wakeners believe they can hear the sleepers' dreams. These runestags display a range of emotions in their vigil, signaling the dreams or nightmares of the spirits within.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180415] = { ["name"] = "Winterborn Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Court of Night\n- Revered\nYou must be a member of the Night Fae Covenant.\nSell Price:\n\"Winterborn runestags are blessed by the Winter Queen herself. Their runes flare brilliantly when predators are nearby, warning the entire herd.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
