entries[180581] = { ["name"] = "Hopecrusher Gargon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Once the loyal mount of a House Briarbane lord, it turned on the lord and his retinue. Members of House Briarbane now whisper of a dark Gargon lying in wait even baiting venthyr who venture through the darker parts of the Chalice District of Revendreth.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[180582] = { ["name"] = "Endmire Flyer Tether", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon an Endmire Flyer.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Attracted through portals through which little is known these flying devourers have found a home in the Endmire of Revendreth feeding on the latent anima.\"\nDrop:\nFamu the Infinite\nZone:\nRevendreth" }
